export const CIQUAL_FOODS: CiqualFood[] = RAW.map(r => ({
  id: r[0], name: r[1], category: r[2],
  kcal: r[3], protein: r[4], carbs: r[5], fat: r[6], fiber: r[7],
}));

export const FOOD_CATEGORIES = Array.from(new Set(CIQUAL_FOODS.map(f => f.category))).sort();

export function searchCiqualFoods(query: string, category?: string): CiqualFood[] {
  let results = CIQUAL_FOODS;
  if (category && category !== 'all') {
    results = results.filter(f => f.category === category);
  }
  if (query.trim()) {
    const q = query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
    const words = q.split(/\s+/);
    results = results.filter(f => {
      const name = f.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
      return words.every(w => name.includes(w));
    });
    // Sort by relevance: exact match > starts with > contains
    results.sort((a, b) => {
      const na = a.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
      const nb = b.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
      const aExact = na === q ? 0 : 1;
      const bExact = nb === q ? 0 : 1;
      if (aExact !== bExact) return aExact - bExact;
      const aStarts = na.startsWith(q) ? 0 : 1;
      const bStarts = nb.startsWith(q) ? 0 : 1;
      if (aStarts !== bStarts) return aStarts - bStarts;
      // Shorter names = more precise match
      return na.length - nb.length;
    });
  }
  return results.slice(0, 50);
}